// Browser diagnostic of the actual production parser and presentation decoder.
// Input frames are generated by the real Native preview_transport_probe example.
import { parseNativePreviewFrame } from '../../src/nativeRender'
import { decodeNativePreviewPayload, nativePreviewDisplayHistogram } from '../../src/nativePreviewPresentation'
import { calculateDisplayHistogram } from '../../src/previewPresentation'

export async function verifyNativePreviewTransport(prefix) {
  if (!/^preview-transport-\d+$/.test(prefix)) throw new Error('Invalid owned probe frame prefix')
  const results = {}
  const timings = { jpeg: [], rgba: [] }
  const canvases = {}
  for (const kind of ['jpeg', 'rgba']) {
    const response = await fetch(`/output/playwright/${prefix}-${kind}.bin`)
    if (!response.ok) throw new Error(`Missing Native probe frame: ${kind}`)
    results[kind] = parseNativePreviewFrame(await response.arrayBuffer())
    const canvas = document.createElement('canvas')
    canvas.width = results[kind].width
    canvas.height = results[kind].height
    canvas.setAttribute('aria-label', `Actual Native ${kind} preview`)
    canvas.style.maxWidth = '95vw'
    canvases[kind] = canvas
  }
  let rgbaByteDifferences = 0
  let releasedBitmaps = 0
  for (let round = 0; round < 22; ++round) {
    for (const kind of round % 2 ? ['rgba', 'jpeg'] : ['jpeg', 'rgba']) {
      const context = canvases[kind].getContext('2d', { willReadFrequently: true, colorSpace: 'srgb' })
      const start = performance.now()
      const presentation = await decodeNativePreviewPayload(results[kind])
      try {
        context.drawImage(presentation.image, 0, 0)
        const pixels = context.getImageData(0, 0, results[kind].width, results[kind].height).data
        if (round >= 2) timings[kind].push(performance.now() - start)
        if (kind === 'rgba') {
          for (let index = 0; index < pixels.length; ++index) {
            if (pixels[index] !== results[kind].payload.bytes[index]) ++rgbaByteDifferences
          }
        }
      } finally {
        presentation.release()
      }
      if (kind === 'rgba' && presentation.image.width === 0) ++releasedBitmaps
    }
  }
  if (rgbaByteDifferences !== 0 || releasedBitmaps !== 22) {
    throw new Error(`Presentation regression: ${rgbaByteDifferences} bytes; ${releasedBitmaps} releases`)
  }
  const stats = (samples) => {
    samples.sort((a, b) => a - b)
    return { medianMs: (samples[9] + samples[10]) / 2, p95Ms: samples[18], samplesMs: samples }
  }
  document.body.replaceChildren(...['jpeg', 'rgba'].flatMap((kind) => {
    const label = document.createElement('h2')
    label.textContent = kind === 'jpeg' ? '原生 JPEG 預覽（既有傳輸）' : '原生無損 RGBA8 預覽（新互動傳輸）'
    return [label, canvases[kind]]
  }))
  return { scope: 'Real Native frames + production parser/decoder + Chromium canvas; excludes Tauri IPC and OS presentation',
    width: results.rgba.width, height: results.rgba.height, measuredSamples: 20,
    rgbaByteDifferences, releasedBitmaps, jpeg: stats(timings.jpeg), rgba: stats(timings.rgba),
    userAgent: navigator.userAgent }
}

/** Same real Native RGBA frame, old canvas readback versus production payload histogram.
 * Timings include decode/draw/histogram, not IPC, input scheduling or OS presentation. */
export async function verifyNativeHistogramPresentation(prefix) {
  if (!/^preview-transport-\d+$/.test(prefix)) throw new Error('Invalid owned probe frame prefix')
  const response = await fetch(`/output/playwright/${prefix}-rgba.bin`)
  if (!response.ok) throw new Error('Missing actual Native RGBA frame')
  const result = parseNativePreviewFrame(await response.arrayBuffer())
  if (result.payload.format !== 'rgba8') throw new Error('Expected actual Native RGBA frame')
  const modes = ['readback', 'payload']
  const canvases = Object.fromEntries(modes.map((mode) => {
    const canvas = document.createElement('canvas')
    canvas.width = result.width; canvas.height = result.height
    canvas.setAttribute('aria-label', `Native ${mode} histogram presentation`)
    canvas.style.maxWidth = '95vw'
    return [mode, canvas]
  }))
  const contexts = Object.fromEntries(modes.map((mode) => [mode, canvases[mode].getContext('2d',
    { willReadFrequently: mode === 'readback', colorSpace: 'srgb' })]))
  const times = { readback: [], payload: [] }
  let expectedHistogram
  let prohibitedReadbacks = 0
  let releasedBitmaps = 0
  for (let round = 0; round < 22; ++round) {
    for (const mode of round % 2 ? [...modes].reverse() : modes) {
      const start = performance.now()
      const presentation = await decodeNativePreviewPayload(result)
      try {
        const context = contexts[mode]
        context.drawImage(presentation.image, 0, 0)
        const histogram = mode === 'readback'
          ? calculateDisplayHistogram(context.getImageData(0, 0, result.width, result.height))
          : nativePreviewDisplayHistogram(result, () => {
            ++prohibitedReadbacks
            throw new Error('RGBA histogram attempted canvas readback')
          })
        if (round >= 2) times[mode].push(performance.now() - start)
        if (!expectedHistogram) expectedHistogram = JSON.stringify(histogram)
        if (JSON.stringify(histogram) !== expectedHistogram) throw new Error('Display histogram differs')
      } finally { presentation.release() }
      if (presentation.image.width === 0) ++releasedBitmaps
    }
  }
  // One untimed final read per surface verifies real presented bytes; not part of the hot path.
  let byteDifferences = 0
  for (const mode of modes) {
    const pixels = contexts[mode].getImageData(0, 0, result.width, result.height).data
    for (let i = 0; i < pixels.length; ++i) if (pixels[i] !== result.payload.bytes[i]) ++byteDifferences
  }
  if (byteDifferences || prohibitedReadbacks || releasedBitmaps !== 44) throw new Error('Presentation ownership regression')
  const stats = (values) => {
    const sorted = [...values].sort((a, b) => a - b)
    return { medianMs: (sorted[9] + sorted[10]) / 2, p95Ms: sorted[18], samplesMs: values }
  }
  document.body.replaceChildren(...modes.map((mode) => canvases[mode]))
  return { scope: 'Real Native bytes and production histogram/decoder in Chromium; excludes Tauri IPC and OS presentation',
    width: result.width, height: result.height, byteDifferences, prohibitedReadbacks, releasedBitmaps,
    measuredSamples: 20, readback: stats(times.readback), payload: stats(times.payload), userAgent: navigator.userAgent }
}
